NativeSignal grp2_select_pointer_object(VM& vm, Thread& thread) {
    const uint32_t output = thread.stack.pop();
    if (output == 0) {
        throw std::runtime_error(
            "Grp2:0x3D output pointer must not be null");
    }
    const VM::PointerObjectSelection selection =
        vm.select_display_object_at_pointer();
    if (selection.found) {
        vm.memory().write_u32(output, thread.base, selection.value);
    }
    thread.stack.push(selection.class_id);
    return NativeSignal::Continue;
}
